<?php
require dirname(__DIR__).'/bootstrap.php';requireRole('admin');$pageTitle='Results';$dashboardMode=true;$attemptId=(int)($_GET['attempt']??0);$resultRows=[];$details=[];$pdo=Database::connection();
if($attemptId){$s=$pdo->prepare('SELECT a.*,e.title,e.total_marks,e.passing_marks,e.result_publish_at,u.name student_name FROM exam_attempts a JOIN exams e ON e.id=a.exam_id JOIN users u ON u.id=a.student_id WHERE a.id=?');$s->execute([$attemptId]);$focused=$s->fetch();if($focused){$details=(new Result())->resultDetails($attemptId);}}
$resultRows=(new Result())->forAdmin();require APP_ROOT.'/components/header.php';
?>
<div class="page-heading"><div><h1>Results</h1><p>Review attempts, publish timing and evaluation status.</p></div></div>
<?php if(!empty($focused)): ?><section class="panel"><div class="panel-header"><h2><?= e($focused['student_name']) ?> · <?= e($focused['title']) ?></h2><a href="<?= e(appUrl('admin/results.php')) ?>">Close details</a></div><div class="panel-body"><div class="exam-score-banner"><div><h2><?= e(ucfirst(str_replace('_',' ',$focused['status']))) ?></h2><p class="muted">Submitted <?= dateTime($focused['submitted_at']) ?> · Result release <?= dateTime($focused['result_publish_at']) ?></p></div><div class="exam-score-number"><?= $focused['obtained_marks']===null?'Pending':e(money($focused['obtained_marks'])).' / '.e(money($focused['total_marks'])) ?></div></div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Question</th><th>Answer</th><th>Score</th></tr></thead><tbody><?php foreach($details as $detail): ?><tr><td><?= e($detail['question_text']) ?></td><td><?php $chosen=array_values(array_filter($detail['options'],fn($o)=>$o['selected']));echo e($detail['answer_text']??(implode(', ',array_column($chosen,'option_text'))?:'Unanswered')); ?></td><td><?= $detail['marks_awarded']===null?'Pending':e(money($detail['marks_awarded'])).' / '.e(money($detail['marks'])) ?></td></tr><?php endforeach; ?></tbody></table></div></div></section><?php endif; ?>
<section class="panel"><div class="panel-header"><h2>All attempts</h2><span class="badge badge-blue"><?= count($resultRows) ?> attempts</span></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Examination</th><th>Class</th><th>Submitted</th><th>Score</th><th>Result</th><th></th></tr></thead><tbody><?php foreach($resultRows as $row): $published=$row['status']==='evaluated'&&(!$row['result_publish_at']||new DateTimeImmutable($row['result_publish_at'])<=new DateTimeImmutable());$pass=$row['obtained_marks']!==null&&(float)$row['obtained_marks']>=(float)$row['passing_marks']; ?><tr><td><strong><?= e($row['student_name']) ?></strong><br><small class="muted"><?= e($row['student_email']) ?></small></td><td><?= e($row['title']) ?></td><td><?= e($row['class_name']) ?></td><td><?= dateTime($row['submitted_at']) ?></td><td><?= $row['obtained_marks']===null?'—':e(money($row['obtained_marks'])).' / '.e(money($row['total_marks'])) ?></td><td><?php if(!$published): ?><span class="badge badge-amber">Not published</span><?php else: ?><span class="badge <?= $pass?'badge-green':'badge-red' ?>"><?= $pass?'Passed':'Not passed' ?></span><?php endif; ?></td><td><a class="button button-outline button-small" href="<?= e(appUrl('admin/results.php?attempt='.(int)$row['id'])) ?>">Details</a></td></tr><?php endforeach; ?><?php if(!$resultRows): ?><tr><td colspan="7"><div class="empty-state">No examination attempts have been submitted yet.</div></td></tr><?php endif; ?></tbody></table></div></div></section>
<?php require APP_ROOT.'/components/footer.php'; ?>
